const FACE_BASE = '<path d="M78,34 C82,16 118,16 122,34"/><path d="M84,35.2 C87,32.8 92.5,32.8 95.5,34.6"/><path d="M116,35.2 C113,32.8 107.5,32.8 104.5,34.6"/><path d="M84.5,41 C88,37.2 93.5,37.2 96,41 C93,44 87.5,44 84.5,41 Z" fill="#FFFFFF"/><path d="M115.5,41 C112,37.2 106.5,37.2 104,41 C107,44 112.5,44 115.5,41 Z" fill="#FFFFFF"/><path d="M89,70 C94,73.5 106,73.5 111,70"/><path d="M92,77 C93,82 94,86 96,89"/><path d="M108,77 C107,82 106,86 104,89"/>';
