const MOUTH = '<path d="M93.5,62.5 C96.5,60.8 103.5,60.8 106.5,62.5"/><path d="M95,63.4 C97.5,65.6 102.5,65.6 105,63.4"/>';
const IRIS = '<circle cx="90.3" cy="41" r="2.1"/><circle cx="109.7" cy="41" r="2.1"/>';

/** 칠할 도형이 있는 부위만. 눈·코·입은 선 색만 바뀌므로 여기 없다. */
const REGION_SHAPES: Partial<Record<BodyRegion, string>> = {
  head: '<ellipse cx="100" cy="42" rx="30" ry="36"/>',
  ears: '<ellipse cx="125" cy="44" rx="7" ry="11"/><ellipse cx="75.0" cy="44" rx="7" ry="11"/>',
  neck: '<ellipse cx="100" cy="84" rx="16" ry="12"/>',
  chest: '<ellipse cx="100" cy="128" rx="44" ry="30"/>',
  abdomen: '<ellipse cx="100" cy="176" rx="36" ry="28"/>',
  pelvis: '<ellipse cx="100" cy="220" rx="38" ry="26"/>',
  joints: '<ellipse cx="147" cy="106" rx="19" ry="17"/><ellipse cx="53.0" cy="106" rx="19" ry="17"/><ellipse cx="157" cy="186" rx="16" ry="19"/><ellipse cx="43.0" cy="186" rx="16" ry="19"/><ellipse cx="153" cy="258" rx="13" ry="15"/><ellipse cx="47.0" cy="258" rx="13" ry="15"/><ellipse cx="118" cy="324" rx="15" ry="23"/><ellipse cx="82.0" cy="324" rx="15" ry="23"/>',
};

type Props = {
  regions: BodyRegion[];
  height?: number;
};

/**
 * 약이 쓰이는 몸의 부위를 그림으로 보여 준다.
 *
 * 그림은 설명을 돕는 보조 수단이다. 근거가 되는 문장은 바로 아래 효능효과
 * 원문이고, 그림은 거기에 적힌 부위만 칠한다.
 */
export function BodyMap({ regions, height = 320 }: Props) {
  const whole = regions.includes('skin');
  const bodyFill = whole ? MARK_FILL : BASE_FILL;
  const bodyStroke = whole ? colors.danger : BASE_STROKE;
  const highlights = regions.map((region) => REGION_SHAPES[region] ?? '').join('');
  const tint = (region: BodyRegion) => (regions.includes(region) ? colors.danger : LINE);

  const xml = `<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 480">
  <defs><clipPath id="b"><path d="${OUTLINE}"/></clipPath></defs>
  <path d="${OUTLINE}" fill="${bodyFill}" stroke="${bodyStroke}" stroke-width="2"/>
  <g clip-path="url(#b)" fill="${MARK_FILL}">${highlights}</g>
  <g clip-path="url(#b)" fill="none" stroke="${LINE}" stroke-width="1.1" stroke-linecap="round" opacity="0.9">
    <g>${HALF}</g><g transform="translate(200,0) scale(-1,1)">${HALF}</g>${CENTER}
  </g>
  <path d="${OUTLINE}" fill="none" stroke="${bodyStroke}" stroke-width="2"/>
  <g fill="none" stroke="${LINE}" stroke-width="1.15" stroke-linecap="round">${FACE_BASE}</g>
  <g fill="none" stroke="${tint('nose')}" stroke-width="1.15" stroke-linecap="round">${NOSE}</g>
  <g fill="none" stroke="${tint('mouth')}" stroke-width="1.15" stroke-linecap="round">${MOUTH}</g>
  <g fill="${tint('eyes')}">${IRIS}</g>
</svg>`;

  return (
    <View style={styles.wrap}>
      <SvgXml xml={xml} width={height * (200 / 480)} height={height} />
      <Text style={styles.caption}>빨갛게 표시된 곳에 쓰는 약입니다</Text>
    </View>
  );
}

const styles = StyleSheet.create({
  wrap: { alignItems: 'center', gap: spacing.sm },
  caption: { ...type.caption, color: colors.textSecondary },
});
